<?php
$projects = array_values(array_filter($site['portfolioProjects'], fn(array $project): bool => $project['portfolioPlacement'] !== 'hidden'));
$featured = array_slice(array_values(array_filter($projects, fn(array $project): bool => $project['portfolioPlacement'] === 'featured')), 0, 6);
$homeFeatured = array_values(array_filter($featured, fn(array $project): bool => $project['homePlacement'] === 'featured'));
$mobileIds = array_column(array_slice($homeFeatured ?: $featured, 0, 4), 'id');
$archive = array_filter($projects, fn(array $project): bool => $project['portfolioPlacement'] === 'archive');
?>
<div id="portfolio-view"><div class="figma-portfolio-page site-mobile-layout <?= c('portfolio', 'page') ?>" id="top"><section class="<?= c('portfolio', 'intro') ?>"><div class="<?= c('portfolio', 'heading') ?>"><?php breadcrumbs('Портфолио'); ?><h1>Сайты и интерфейсы,<br class="<?= c('portfolio', 'desktopBreak') ?>"> которые я спроектировал</h1></div><div class="<?= c('portfolio', 'updated') ?>"><span><small>Последнее обновление</small><strong><?= h(date('d.m.Y', strtotime($content['updatedAt']))) ?></strong></span><?php image('/assets/figma/portfolio-update.svg', '', ['class' => c('portfolio', 'desktopUpdateIcon'), 'width' => 28, 'height' => 28]); image('/assets/figma/portfolio-update-mobile.svg', '', ['class' => c('portfolio', 'mobileUpdateIcon'), 'width' => 24, 'height' => 24]); ?></div></section>
<section class="<?= c('portfolio', 'work') ?>" aria-labelledby="featured-title"><div class="<?= c('portfolio', 'workTextureTop') ?>" aria-hidden="true"></div><div class="<?= c('portfolio', 'workTextureBottom') ?>" aria-hidden="true"></div><div class="<?= c('portfolio', 'workInner') ?>"><div class="<?= c('portfolio', 'sectionTitle') ?>"><span>{Лучшее}</span><h2 id="featured-title">Избранные проекты</h2></div><div class="<?= c('portfolio', 'featuredGrid') ?>" id="featured-projects"><?php foreach ($featured as $index => $project) project_card($project, c('portfolio', 'featuredCard') . ' ' . (in_array($project['id'], $mobileIds, true) ? '' : c('portfolio', 'extraCard')), $index < 3); ?></div>
<h2 class="<?= c('portfolio', 'otherTitle') ?>" id="other">Другие проекты</h2><div class="<?= c('portfolio', 'filters') ?>" role="group" aria-label="Фильтр проектов"><?php foreach (['Все', 'Tilda', 'Одностраничные', 'Многостраничные', 'Интернет-магазины', 'Интерфейсы'] as $index => $label): ?><button type="button" class="<?= $index === 0 ? c('portfolio', 'activeFilter') : '' ?>" aria-pressed="<?= $index === 0 ? 'true' : 'false' ?>"><?= h($label) ?></button><?php endforeach; ?></div><div class="<?= c('portfolio', 'projectList') ?>" id="archive-projects" aria-live="polite"><?php foreach ($archive as $project) project_row($project, c('portfolio', 'projectRow')); ?></div><?php if (count($featured) > 4 || count($archive) > 5) all_projects(count($projects), c('portfolio', 'allProjects'), '#archive-projects'); ?></div></section><?php require __DIR__ . '/services.php'; ?></div></div>
